kit.base:
*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--text-md);
  line-height: var(--leading-body);
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3,
p,
figure {
  margin: 0;
}

h1 {
  font-size: var(--text-2xl);
  line-height: var(--leading-tight);
  letter-spacing: -0.01em;
}

h2 {
  font-size: var(--text-xl);
  line-height: var(--leading-tight);
}

a {
  color: var(--accent);
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

sheets.ui:
.stack {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}

.muted {
  color: var(--text-muted);
  font-size: var(--text-sm);
}

.field {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.field > label {
  font-size: var(--text-sm);
  color: var(--text-muted);
}

sheets.kit:
/* A ground of its own, and deliberately neither the design's dark nor white:
   a dark part on a dark sheet and a light part on a light one both disappear
   into it, and half of what a kit is for is seeing the edges of things. A mid
   grey is a poor background for nothing in particular, which is what makes it
   a good one here — and it says at a glance that this screen is the kit
   rather than the product. */
.kit {
  --kit-ground: #9aa0ab;
  --kit-ink: #14171d;
  --kit-ink-soft: #3b414d;
  --kit-rule: rgba(0, 0, 0, 0.22);

  display: flex;
  flex-direction: column;
  gap: var(--space-6, 32px);
  padding: var(--space-6, 32px);
  font-family: var(--font-sans, system-ui, sans-serif);
  color: var(--kit-ink);
  background: var(--kit-ground);
  /* The ground reaches the bottom of whatever it is drawn in.
     A sheet stores ONE height, and its parts are now drawn in windows at the
     viewport being looked at — so the sheet is a few hundred pixels shorter on
     a phone than the size it was measured at. Without this that difference was
     a band of the design's own black under the page, which reads as a bug in
     the sheet rather than as slack. */
  min-height: 100dvh;
  /* No 100vh: a sheet measures itself and the frame is its own height, so a
     minimum in viewport units would only stretch it to whatever the browser
     happened to be when it was measured. */
}

.kit__head h1 {
  margin: 0;
  font-size: var(--text-2xl, 1.75rem);
}

.kit-note,
.kit-value,
.kit-desc,
.kit-tier {
  color: var(--kit-ink-soft);
  font-size: var(--text-sm, 0.875rem);
}

.kit code {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: var(--text-sm, 0.8125rem);
}

.kit__foot {
  margin-top: auto;
  padding-top: var(--space-5, 24px);
  border-top: 1px solid var(--kit-rule);
  color: var(--kit-ink-soft);
  font-size: var(--text-xs, 0.75rem);
}

.kit-swatches {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: var(--space-4, 16px);
}

.kit-swatch {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2, 8px);
}

.kit-chip {
  height: 64px;
  border-radius: var(--radius-md, 10px);
  border: 1px solid var(--kit-rule);
}

.kit-swatch figcaption {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.kit-rows {
  display: flex;
  flex-direction: column;
  gap: var(--space-3, 12px);
}

.kit-row {
  display: grid;
  grid-template-columns: 12rem 1fr 6rem;
  align-items: center;
  gap: var(--space-4, 16px);
}

/* The sample is about the FACE and its size — colour is the swatches' job —
   so it is read in the sheet's own ink rather than the design's. */
.kit-sample {
  color: var(--kit-ink);
}

.kit-bar {
  height: 12px;
  min-width: 2px;
  /* A size token can be wider than the page it is drawn on — --shell-max is
   * 1440px, the kit sheet is not much wider — and an uncapped bar pushed its
   * own "1440px" caption off the right edge, the one token whose value you
   * then could not read. Cap it; the caption carries the true number. */
  max-width: 100%;
  border-radius: 2px;
  background: var(--accent, #4f7cf7);
}

.kit-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--space-2, 8px);
}

.kit-list > div {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3, 12px);
  padding: var(--space-2, 8px) 0;
  border-bottom: 1px solid var(--kit-rule);
}

.kit-part {
  display: flex;
  flex-direction: column;
  gap: var(--space-3, 12px);
  padding-top: var(--space-4, 16px);
  border-top: 1px solid var(--kit-rule);
}

.kit-part__head {
  display: flex;
  align-items: baseline;
  gap: var(--space-3, 12px);
  flex-wrap: wrap;
}

.kit-variants {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4, 16px);
}

.kit-variant {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2, 8px);
}

.kit-variant figcaption {
  color: var(--kit-ink-soft);
  font-size: var(--text-xs, 0.75rem);
}

.kit-icons {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(112px, 1fr));
  gap: var(--space-3, 12px);
}

.kit-icon {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-2, 8px);
}

/* Stroke by default — see iconsSection. */
.kit-glyph {
  width: 26px;
  height: 26px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.kit-icons--fill .kit-glyph {
  fill: currentColor;
  stroke: none;
}

/* The parts themselves are drawn on the DESIGN's ground, not the sheet's: an
   icon meant for a dark app is invisible on grey, and what a kit has to show
   is the thing as it really looks. The grey is around them, not under them. */
.kit-icon__stage {
  width: 100%;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--kit-rule);
  border-radius: var(--radius-md, 10px);
  /* Self-contained, NOT the design's --bg/--text. Those names belong to the
   * starter kit's vocabulary; a project that brings its own leaves --text
   * undefined, the fallback was near-white, and an icon came out light on a
   * light --bg — invisible. The kit's own ink on a plain white chip is legible
   * whatever a design calls its tokens. (A theme-specific icon still wants
   * rendering in the design's own context, the way components already are — a
   * later change; this only stops the disappearing act.) */
  background: #fff;
  color: var(--kit-ink);
}

.kit-icon figcaption {
  color: var(--kit-ink-soft);
  font-size: var(--text-xs, 0.75rem);
  text-align: center;
  /* A name like icon-check:default is longer than its cell, and a grid that
     stretches to its longest caption stops being a grid. */
  overflow-wrap: anywhere;
}

/* A region of a layout has no appearance of its own, so the sheet gives it a
   dashed outline and its name — and NOTHING ELSE. No size, no position: those
   belong to the region it was poured into, and a label that laid itself out
   would be showing the label's arrangement rather than the layout's. */
.kit-region {
  padding: var(--space-2, 8px);
  border: 1px dashed currentcolor;
  border-radius: var(--radius-sm, 6px);
  color: var(--text-muted, #8b93a7);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: var(--text-xs, 0.75rem);
  text-align: center;
}

/* The body region is the one that takes the space left over, so its label
   fills what it was given rather than sitting at the top of it. */
.kit-page main > .kit-region {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Shells sit side by side, one per viewport, and are read left to right. */
.kit-part--layout .kit-variants {
  align-items: flex-start;
  gap: var(--space-6, 32px);
}

/* A shell is shown in a frame of its own — see layoutRow. The frame is drawn
   at the viewport's real width and scaled down to fit the sheet, so what it
   lays out is what that viewport gets. */
/* Two classes deep on purpose: .kit-stage comes later in this sheet and would
   otherwise win on source order and centre the frame again. */
.kit-stage.kit-stage--frame {
  /* Top left, not centred. A cell centres what is in it, and a frame is BIGGER
     than its cell — it is 1440 wide and scaled down to fit — so centring the
     layout box put it 130px to the left and 56px above the cell, with the
     header clipped away by the overflow. */
  align-items: flex-start;
  justify-content: flex-start;
  overflow: hidden;
  border: 0;
  padding: 0;
  background: none;
  min-width: 0;
  min-height: 0;
}

/* A PART keeps the card this sheet has always drawn — the design's ground, a
   hairline, and air around it — and the window it is really drawn in becomes
   invisible inside that card.

   Which is the whole trick: the air cannot go INSIDE the frame, because a
   message band bleeds to the width of what contains it and padding there would
   stop it. So it goes outside, on the card, and the crop sits between them. Put
   the border on the frame instead and it hugs the part — a send button came out
   as a circle in a 48px box with a line drawn tight around it. */
.kit-crop {
  overflow: hidden;
  /* An iframe is inline, and an inline box sits on the baseline with a few
     pixels of descender space under it. */
  line-height: 0;
}

.kit-stage--part .kit-frame {
  display: block;
  border: 0;
  border-radius: 0;
  background: none;
}

.kit-frame {
  /* The frame carries its own document, so the design's ground is inside it
     and the sheet's grey stops at its border. */
  /* Never shrunk to the cell: a frame is a WINDOW, and its width is what the
     design's media queries answer to. As a flex item it shrank from 1440 to
     the 1180 the sheet had room for, and the shell inside laid itself out with
     the phone rules — the one thing this frame exists to avoid. */
  flex: none;
  border: 1px solid var(--border, #2b303b);
  border-radius: var(--radius-lg, 18px);
  transform-origin: top left;
  background: var(--bg, #0f1116);
}

/* A part is drawn on the DESIGN's ground, inside the sheet's grey — that is
   what puts an edge around it. Centred, so a row of variants lines up. */
/* A part frame holds one part, not a page. It keeps the design's page class —
   that is where the typeface, the ink and the ground come from, and without it
   every part renders in Times on white — and gives up only the page GEOMETRY:
   a full-height flex column that becomes a grid at 1200px would make a chip as
   tall as a phone and auto-place it into a cell it never asked for.

   Written with the element on purpose. A bare .kit-part-page ties with .app on
   specificity, and the tie would be settled by whichever stylesheet the
   composer happened to put last — including the one that turns .app into a
   grid inside a media query, which is the case that matters. One extra element
   in the selector settles it instead.

   No padding: a client's message band bleeds to the width of what contains it,
   and padding here would quietly stop it doing that. */
/* Block flow, so a band is as wide as what contains it and a pill is as wide
   as its words — the same two answers the design gives. Making this a flex
   column was tried, to give an inline pip a box, and it cost the other half:
   with flex-start every full-width block shrank to its content, and the order
   strip cropped its own status pill off the right. The pip is fixed where the
   pip is the problem — see the fit script. */
body.kit-part-page {
  margin: 0;
  display: block;
  height: auto;
  min-height: 0;
  overflow: visible;
}

.kit-stage {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 140px;
  min-height: 72px;
  padding: var(--space-3, 12px);
  border: 1px solid var(--kit-rule);
  border-radius: var(--radius-md, 10px);
  background: var(--bg, #0f1116);
  color: var(--text, #e6e8ee);
}

sheets.pages:
.hero { display: flex; flex-direction: column; gap: var(--space-4); align-items: flex-start; padding: var(--space-6) 0; }
.hero__title { margin: 0; font-size: var(--text-2xl); max-width: 20ch; line-height: var(--leading-tight); }
.hero__sub { margin: 0; color: var(--text-muted); font-size: var(--text-lg); max-width: 52ch; }
.hero__cta { display: flex; gap: var(--space-3); }
.features { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-5); }
.tiers { display: grid; grid-template-columns: repeat(2, minmax(0, 320px)); gap: var(--space-5); }
.stat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-4); }
.board { display: flex; gap: var(--space-4); align-items: flex-start; overflow-x: auto; }
.table { display: flex; flex-direction: column; border: var(--border-width) solid var(--border); border-radius: var(--radius-md); overflow: hidden; }
.table__head { display: grid; grid-template-columns: 1fr auto auto 7rem; gap: var(--space-4); padding: var(--space-3) var(--space-4); background: var(--surface-2); color: var(--text-muted); font-size: var(--text-sm); }
.detail { display: grid; grid-template-columns: 2fr 1fr; gap: var(--space-5); align-items: start; }
.panel { display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-4); border: var(--border-width) solid var(--border); border-radius: var(--radius-md); background: var(--surface); }
.section-title { font-size: var(--text-lg); font-weight: 600; }

button.css:
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  border: var(--border-width) solid transparent;
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: var(--accent-text);
  font-weight: 600;
  cursor: pointer;
}
.button--quiet {
  background: transparent;
  border-color: var(--border-strong);
  color: var(--text);
}
.button--danger {
  background: var(--danger);
  color: var(--bg);
}

pill.css:
.pill {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: 2px var(--space-2);
  border-radius: var(--radius-pill);
  font-size: var(--text-xs);
  font-weight: 600;
  background: var(--surface-2);
  color: var(--text-muted);
}
.pill::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.pill--todo { background: var(--surface-2); color: var(--text-muted); }
.pill--doing { background: var(--accent-soft); color: var(--accent); }
.pill--done { background: color-mix(in srgb, var(--success) 18%, transparent); color: var(--success); }
.pill--blocked { background: color-mix(in srgb, var(--danger) 18%, transparent); color: var(--danger); }

avatar.css:
.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: var(--text-xs);
  font-weight: 700;
}

tag.css:
.tag {
  display: inline-flex;
  align-items: center;
  padding: 2px var(--space-2);
  border-radius: var(--radius-pill);
  background: var(--accent-soft);
  color: var(--accent);
  font-size: var(--text-xs);
  font-weight: 600;
}

icon.css:
.icon {
  width: 20px;
  height: 20px;
  flex: none;
  color: currentColor;
}

input.css:
.input {
  width: 100%;
  padding: var(--space-3);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font: inherit;
}
.input:focus {
  border-color: var(--accent);
  outline: none;
}
.input::placeholder { color: var(--text-muted); }

checkbox.css:
.checkbox {
  display: inline-block;
  width: 18px;
  height: 18px;
  border: var(--border-width) solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
}
.checkbox--on {
  border-color: var(--accent);
  background: var(--accent);
  position: relative;
}
.checkbox--on::after {
  content: '';
  position: absolute;
  left: 5px;
  top: 1px;
  width: 5px;
  height: 10px;
  border: solid var(--accent-text);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

link.css:
.link {
  color: var(--accent);
  text-decoration: none;
  font-weight: 500;
}
.link:hover { text-decoration: underline; }

nav-item.css:
.nav-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
}
.nav-item:hover { background: var(--surface-2); color: var(--text); }
.nav-item--active { background: var(--accent-soft); color: var(--accent); }
.nav-item__bar {
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 3px;
  border-radius: var(--radius-pill);
  background: var(--accent);
}

task-card.css:
.task-card {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-4);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface);
}
.task-card__row { display: flex; align-items: center; justify-content: space-between; }
.task-card__title { margin: 0; font-size: var(--text-md); }
.task-card__meta { margin: 0; color: var(--text-muted); font-size: var(--text-sm); }

stat-card.css:
.stat-card {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  padding: var(--space-4);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface);
}
.stat-card__label { color: var(--text-muted); font-size: var(--text-sm); }
.stat-card__value { font-size: var(--text-2xl); }
.stat-card__delta { color: var(--success); font-size: var(--text-xs); font-weight: 600; }

list-row.css:
.list-row {
  display: grid;
  grid-template-columns: 1fr auto auto 7rem;
  align-items: center;
  gap: var(--space-4);
  padding: var(--space-3) var(--space-4);
  border-bottom: var(--border-width) solid var(--border);
}
.list-row__title { font-weight: 500; }
.list-row__when { color: var(--text-muted); font-size: var(--text-sm); text-align: right; }

member-row.css:
.member-row {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) 0;
  border-bottom: var(--border-width) solid var(--border);
}
.member-row__id { display: flex; flex-direction: column; margin-right: auto; }
.member-row__email { color: var(--text-muted); font-size: var(--text-sm); }

comment.css:
.comment { display: flex; gap: var(--space-3); }
.comment__body { display: flex; flex-direction: column; gap: var(--space-1); }
.comment__head { display: flex; align-items: baseline; gap: var(--space-2); }
.comment__when { color: var(--text-muted); font-size: var(--text-xs); }
.comment__text { margin: 0; }

feature.css:
.feature { display: flex; flex-direction: column; gap: var(--space-2); }
.feature__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--accent-soft);
  color: var(--accent);
}
.feature__title { margin: 0; font-size: var(--text-lg); }
.feature__text { margin: 0; color: var(--text-muted); }

tier.css:
.tier {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-5);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
}
.tier--featured { border-color: var(--accent); box-shadow: var(--shadow); }
.tier__head { display: flex; flex-direction: column; gap: var(--space-1); }
.tier__name { margin: 0; font-size: var(--text-lg); }
.tier__price { font-size: var(--text-2xl); font-weight: 700; }
.tier__feats { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: var(--space-2); color: var(--text-muted); }

sidebar.css:
.sidebar {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
  width: 232px;
  flex: none;
  padding: var(--space-5) var(--space-4);
  border-right: var(--border-width) solid var(--border);
  background: var(--surface);
}
.sidebar__brand { display: flex; align-items: center; gap: var(--space-2); font-weight: 700; color: var(--text); }
.sidebar__brand .icon { color: var(--accent); }
.sidebar__nav { display: flex; flex-direction: column; gap: var(--space-1); }
.sidebar__foot { margin-top: auto; }
.sidebar--mini { width: 64px; align-items: center; }
.sidebar--mini .sidebar__name { display: none; }

topbar.css:
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  padding: var(--space-4) var(--space-5);
  border-bottom: var(--border-width) solid var(--border);
  background: var(--surface);
}
.topbar__title { font-size: var(--text-lg); font-weight: 600; }
.topbar__actions { display: flex; align-items: center; gap: var(--space-3); }

board-column.css:
.board-col {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  width: 288px;
  flex: none;
  padding: var(--space-3);
  border-radius: var(--radius-md);
  background: var(--surface-2);
}
.board-col__head { display: flex; align-items: center; justify-content: space-between; padding: 0 var(--space-2); font-weight: 600; }
.board-col__body { display: flex; flex-direction: column; gap: var(--space-3); }

modal.css:
.modal-scrim {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-5);
  background: var(--scrim);
}
.modal {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  width: 100%;
  max-width: 480px;
  padding: var(--space-5);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow);
}
.modal__head { display: flex; align-items: center; justify-content: space-between; }
.modal__title { margin: 0; font-size: var(--text-lg); }
.modal__body { display: flex; flex-direction: column; gap: var(--space-3); }
.modal__foot { display: flex; justify-content: flex-end; gap: var(--space-2); }

app-shell.css:
.app { display: flex; min-height: 100vh; background: var(--bg); color: var(--text); }
.app__main { display: flex; flex-direction: column; flex: 1; min-width: 0; }
.app__content { flex: 1; padding: var(--space-6) var(--space-5); display: flex; flex-direction: column; gap: var(--space-5); }

marketing-shell.css:
.marketing { min-height: 100vh; background: var(--bg); color: var(--text); }
.mkt-nav { display: flex; align-items: center; justify-content: space-between; padding: var(--space-4) var(--space-6); border-bottom: var(--border-width) solid var(--border); }
.mkt-nav__brand { display: flex; align-items: center; gap: var(--space-2); font-weight: 700; }
.mkt-nav__brand .icon { color: var(--accent); }
.mkt-nav__links { display: flex; align-items: center; gap: var(--space-4); }
.mkt-main { max-width: 1080px; margin: 0 auto; padding: var(--space-7) var(--space-6); display: flex; flex-direction: column; gap: var(--space-7); }
.mkt-foot { padding: var(--space-6); border-top: var(--border-width) solid var(--border); color: var(--text-muted); text-align: center; }
